const atlasIntroductions={"place-vivienne": {"intro": "巴黎右岸的一条有玻璃顶的商业长廊，店铺沿通道排列，以马赛克地面著称。它既是穿行的捷径，也是购物、停留和观看橱窗的室内街道。", "sources": [{"label": "百科身份资料 · Galerie Vivienne", "url": "https://en.wikipedia.org/wiki/Galerie_Vivienne"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Galerie_Vivienne"}]}, "place-vero": {"intro": "维罗—多达是一条连接巴黎街道的有顶商业长廊，黑白相间的地面形成鲜明透视。理解它时，可以先把它想成一条两侧开店、屋顶透光的小街。", "sources": [{"label": "百科身份资料 · Galerie Véro-Dodat", "url": "https://en.wikipedia.org/wiki/Galerie_V%C3%A9ro-Dodat"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Galerie_V%C3%A9ro-Dodat"}]}, "place-panoramas": {"intro": "巴黎早期有顶商业通道之一，名称来自曾在附近展示的全景画。商铺、餐饮与观看奇观的人群，使它成为消费和娱乐相遇的地方。", "sources": [{"label": "百科身份资料 · Passage des Panoramas", "url": "https://en.wikipedia.org/wiki/Passage_des_Panoramas"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Passage_des_Panoramas"}]}, "place-caire": {"intro": "巴黎右岸的商业通道，名称带有当时法国对埃及的想象。它展示了城市商业如何借用遥远地域的名称和装饰吸引顾客。", "sources": [{"label": "百科身份资料 · Passage des Panoramas", "url": "https://en.wikipedia.org/wiki/Passage_des_Panoramas"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Passage_du_Caire"}]}, "place-colbert": {"intro": "靠近薇薇安长廊的有顶通道，以圆形大厅和玻璃顶形成开阔的室内空间。它让街道、商铺与大厅之间的界限变得模糊。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Galerie_Colbert"}]}, "place-opera": {"intro": "曾经位于巴黎歌剧院街区的商业通道，后来在城市改造中消失。书中所写的是历史上的旧通道，不能把它与今天的歌剧院建筑混为一处。", "sources": [{"label": "百科身份资料 · Avenue de l'Opéra", "url": "https://en.wikipedia.org/wiki/Avenue_de_l%27Op%C3%A9ra"}]}, "place-desir": {"intro": "巴黎历史通道中的一个名称，法文意思是“欲望”。它首先是一处城市通路；名称引出的联想，与具体建筑的沿革应分开理解。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Passage_du_D%C3%A9sir"}]}, "place-princes": {"intro": "巴黎右岸的一条有顶商业长廊，体现了沿通道组织商铺的经营方式。这里的“王子”是地名，不表示整条通道属于某位王子的私人住宅。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Passage_des_Princes"}]}, "place-pontneuf-passage": {"intro": "旧巴黎一条后来消失的商业通道，名称借用了新桥。它与横跨塞纳河的新桥不是同一座建筑。", "sources": []}, "place-bois": {"intro": "皇家宫殿花园周边曾出现的木构商业长廊，聚集店铺与来往人群。这里指历史上的商业设施，不是一座独立的木桥。", "sources": []}, "place-royal": {"intro": "皇家宫殿及其花园、沿廊店铺构成的城市街区。人们来这里散步、消费、交谈；宫殿周边的公共生活，与宫殿本身同样重要。", "sources": [{"label": "百科身份资料 · Palais-Royal", "url": "https://en.wikipedia.org/wiki/Palais-Royal"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Palais-Royal"}]}, "place-grevin": {"intro": "以蜡像展示人物与场面的巴黎博物馆。蜡像把名人、新闻和历史变成可以近距离观看的形象，是都市娱乐的一种形式。", "sources": [{"label": "百科身份资料 · Musée Grévin", "url": "https://en.wikipedia.org/wiki/Mus%C3%A9e_Gr%C3%A9vin"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Mus%C3%A9e_Gr%C3%A9vin"}]}, "place-saintlazare": {"intro": "巴黎的重要铁路终点站之一，连接列车、旅客、搬运与城市交通。火车带来的速度，也依靠站台上持续进行的劳动。", "sources": [{"label": "百科身份资料 · Gare Saint-Lazare", "url": "https://en.wikipedia.org/wiki/Gare_Saint-Lazare"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Gare_de_Paris-Saint-Lazare"}]}, "place-richelieu": {"intro": "法国国家图书馆位于巴黎黎塞留街区的历史馆址。它是收藏与研究文献的地方，也是本雅明研究巴黎时的重要工作场所。", "sources": [{"label": "百科身份资料 · Bibliothèque nationale de France", "url": "https://en.wikipedia.org/wiki/Biblioth%C3%A8que_nationale_de_France"}]}, "place-lauzun": {"intro": "圣路易岛上的历史宅邸，也称皮莫丹府邸，曾与波德莱尔等人的文学生活发生联系。法文 hôtel 在这里指城市私人宅邸，并非旅馆。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/H%C3%B4tel_de_Lauzun"}]}, "place-lorette": {"intro": "巴黎的一座教堂及其周边街区。文学中的“洛雷特女郎”另有社会含义，不能把一个历史称呼直接等同于这里的所有女性居民。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/%C3%89glise_Notre-Dame-de-Lorette_de_Paris"}]}, "place-bastille": {"intro": "这里指巴士底及其革命记忆所形成的城市空间。旧堡垒与今天的广场不是同一个物体，地名却保留了革命、集会和政治行动的联想。", "sources": [{"label": "百科身份资料 · Place de la Bastille", "url": "https://en.wikipedia.org/wiki/Place_de_la_Bastille"}, {"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Place_de_la_Bastille"}]}, "place-madeleine": {"intro": "巴黎玛德莱娜教堂及其周边街区，建筑外形具有古典柱廊特征。宗教建筑与周边商业共同组成读者在书中遇见的城市景观。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/%C3%89glise_de_la_Madeleine"}]}, "place-bonmarche": {"intro": "巴黎的百货商店，常与布西科的经营革新联系在一起。与小店不同，百货店把多类商品、陈列和顾客活动集中到同一建筑中。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Le_Bon_March%C3%A9"}]}, "place-pontneuf": {"intro": "横跨塞纳河的新桥，是巴黎历史悠久的桥梁。“新”是沿用下来的名称，不表示它今天仍是一座新建的桥。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Pont_Neuf"}]}, "place-halles": {"intro": "旧巴黎集中供应和交易食品的中央市场区域。摊贩、搬运、批发与日常采购在此相遇，城市繁华由这样的供应网络维持。", "sources": []}, "place-catacombs": {"intro": "由旧采石场地下空间改用而成的藏骨处。它既涉及墓地迁移，也让读者看到地面城市下面的另一层历史。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Catacombes_de_Paris"}]}, "place-champs": {"intro": "巴黎著名的林荫大道，沿线的散步、展示与消费共同塑造了它的公众形象。书中的大道经验属于特定历史时期。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Avenue_des_Champs-%C3%89lys%C3%A9es"}]}, "place-commerce": {"intro": "圣安德烈商业中庭是一处连接街巷的巴黎历史通道。中庭、铺面与旧街道保留了大规模道路改造之外的另一种城市尺度。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Cour_du_Commerce-Saint-Andr%C3%A9"}]}, "place-maubert": {"intro": "导览涉及的旧巴黎盲巷名称，盲巷指不能贯通的街巷。它在这里首先是一条历史地名线索，现存位置与建筑对应仍须谨慎核对。", "sources": []}, "place-miracles": {"intro": "旧巴黎某些贫困聚居区的历史称呼，也被文学不断加工。它不是一处真的会发生奇迹的景点，相关叙述常夹杂外界对贫民的想象。", "sources": []}, "place-cafeanglais": {"intro": "旧巴黎的餐饮场所，名字虽叫“英格兰咖啡馆”，却不能仅按今天的小咖啡店来理解。它联系着餐饮、社交和消费身份。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Caf%C3%A9_Anglais"}]}, "place-regence": {"intro": "巴黎历史上的咖啡馆，以棋局和城市社交著称。咖啡馆不仅售卖饮食，也让陌生人围绕新闻、游戏与谈话聚到一起。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Caf%C3%A9_de_la_R%C3%A9gence"}]}, "place-seine": {"intro": "流经巴黎的河流，两岸连接桥梁、码头、书摊与沿河劳动。它既是景观，也参与城市交通、贸易和日常生活。", "sources": []}, "place-polytechnique": {"intro": "法国的一所高等工程与科学教育机构，历史上与国家建设、技术人才及政治事件相关。它不是泛指巴黎所有理工学校。", "sources": []}, "place-saintdenis": {"intro": "巴黎的一座纪念性城门建筑，也是周边街区的地标。经过城门的人流与商业，使纪念建筑进入普通人的日常道路。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Porte_Saint-Denis"}]}, "place-louvre": {"intro": "本档案主要涉及以卢浮命名的百货商业史，不应直接等同于卢浮宫博物馆。阅读时需留意段落谈的是商店、街区还是宫殿。", "sources": []}, "place-trinite": {"intro": "旧巴黎通道名称之一。这里保留的是导览中可以追踪的历史地名，而非保证今天仍能按同样形态找到的旅游景点。", "sources": []}, "place-cheval": {"intro": "巴黎一处与手工业院落、通道相联系的地名，法文意为“白马”。它提醒人们：通道也可以通向作坊与劳动空间。", "sources": [{"label": "地名资料", "url": "https://fr.wikipedia.org/wiki/Passage_du_Cheval-Blanc"}]}, "place-saumon": {"intro": "旧巴黎商业通道的历史名称，法文 saumon 意为“三文鱼”。书中的地名及相关生活属于旧城语境，不能仅凭名称寻找今日同名商店。", "sources": []}, "person-benjamin": {"intro": "德国思想家、文学批评家，《拱廊街计划》的作者。他通过摘录、笔记和材料并置，研究十九世纪巴黎的商品、建筑与日常经验。", "sources": []}, "person-baudelaire": {"intro": "法国诗人，《恶之花》与《巴黎的忧郁》的作者。他写人群、街道、贫困与孤独，是本雅明理解现代都市经验的重要对象。", "sources": []}, "person-fourier": {"intro": "法国社会思想家，设想以新的共同生活组织改变劳动与欲望的关系。他的社会构想让本雅明把商业建筑与集体生活的梦想联系起来。", "sources": []}, "person-haussmann": {"intro": "主持巴黎大规模城市改造的行政官员。他的名字与新大道、拆迁及城市空间重组相连；“奥斯曼化”因而超出个人生平而成为一个主题。", "sources": []}, "person-grandville": {"intro": "法国讽刺插画家，以动物拟人和奇异物件组合闻名。他的图像帮助读者理解商品世界的幻想与怪诞。", "sources": []}, "person-daguerre": {"intro": "法国图像技术先驱，与达盖尔摄影术及透景画相关。他连接了舞台幻景、观看装置和摄影的历史。", "sources": []}, "person-hugo": {"intro": "法国小说家、诗人与政治人物，《巴黎圣母院》《悲惨世界》的作者。他的作品为阅读旧巴黎及社会冲突提供文学线索。", "sources": []}, "person-balzac": {"intro": "法国小说家，《人间喜剧》的作者。他写金钱、野心、衣着、住宅与交际怎样左右人的生活，让城市由具体人物及其关系显现。", "sources": []}, "person-aragon": {"intro": "法国作家，与超现实主义运动相关，《巴黎的农民》的作者。他对巴黎通道与日常奇景的书写，是理解本雅明计划的一条线索。", "sources": []}, "person-breton": {"intro": "法国诗人和超现实主义运动的重要人物。他对梦、偶遇与日常事物的关注，与本雅明寻找城市陌生面貌的兴趣相接。", "sources": []}, "person-proust": {"intro": "法国小说家，《追忆似水年华》的作者。记忆怎样被气味、物件和不经意的感觉唤起，是他与本雅明之间的重要关联。", "sources": []}, "person-poe": {"intro": "美国小说家、诗人与批评家，写过都市人群和侦探故事。他的文学人物为辨认陌生人、观察与追踪提供了现代城市的模型。", "sources": []}, "person-marx": {"intro": "德国思想家和政治经济学批判者，《资本论》的作者。商品、劳动与资本的分析，是理解本雅明现代都市批判的重要理论背景。", "sources": []}, "person-engels": {"intro": "德国思想家，马克思的合作者，也研究工业城市与工人处境。他让都市经验与生产、居住和阶级关系联系起来。", "sources": []}, "person-blanqui": {"intro": "法国革命活动家，长期参与政治斗争并多次被囚禁。他关于宇宙和重复的思考，也进入了本雅明的历史与时间问题。", "sources": []}, "person-saintsimon": {"intro": "法国社会思想家，关注工业、组织与社会改造。与其思想相关的圣西门主义，参与了十九世纪技术和交通进步的想象。", "sources": []}, "person-simmel": {"intro": "德国社会学家、哲学家，研究金钱、社会交往与大都市生活。个体如何应对城市刺激，是理解相关段落的入口。", "sources": []}, "person-jung": {"intro": "瑞士精神科医生、分析心理学的创立者。他的梦与集体心理概念出现在本雅明处理梦境和历史认识的讨论中。", "sources": []}, "person-freud": {"intro": "精神分析的创立者，研究梦、无意识与记忆。这里首先把他视为一套心理解释方法的提出者，而非巴黎街头人物。", "sources": []}, "person-bloch": {"intro": "德国哲学家，关注希望、乌托邦与尚未实现的可能。他与本雅明同属二十世纪思想讨论的背景，并非十九世纪巴黎居民群像。", "sources": []}, "person-adorno": {"intro": "德国哲学家、音乐理论家，与本雅明有重要思想交往。阅读此档案可留意现代文化批判及相关通信的背景。", "sources": []}, "person-tiedemann": {"intro": "德国学者，本雅明著作的重要编辑者。他参与整理未完成的《拱廊街计划》，帮助后来的读者进入材料结构。", "sources": []}, "person-fittko": {"intro": "帮助流亡者越境的行动者，曾协助本雅明穿越比利牛斯山。她的回忆涉及本雅明生命最后阶段，不属于巴黎十九世纪街头场景。", "sources": []}, "person-hessel": {"intro": "德国作家、翻译家，与本雅明有交往。他的城市漫步书写，为理解观看街道和游荡经验提供了背景。", "sources": []}, "person-nadar": {"intro": "法国摄影家、漫画家，以人物摄影和摄影实验著称。他把新的图像技术带入名人肖像与城市空间的记录。", "sources": []}, "person-meryon": {"intro": "法国版画家，以巴黎城市景观的蚀刻作品著称。他的图像保留了旧城建筑及其气氛，是另一种观看城市的方式。", "sources": []}, "person-daumier": {"intro": "法国画家、版画家和讽刺漫画家。他画政治、司法及普通人的生活，让社会关系成为可以看见的姿态与场面。", "sources": []}, "person-wiertz": {"intro": "比利时画家，作品常带戏剧性与宏大构想。他关于绘画和新图像技术的议论，构成书中艺术媒介问题的一条线索。", "sources": []}, "person-michelet": {"intro": "法国历史学家，以历史叙述与民族、人民的书写著称。读者应留意书中引用者的身份，不把他的话自动归给本雅明。", "sources": []}, "person-valery": {"intro": "法国诗人、散文家和思想者。他对知觉、艺术与现代生活的思考，为相关笔记提供了可对照的声音。", "sources": []}, "person-rimbaud": {"intro": "法国诗人，以对诗歌语言和感官经验的探索著称。他首先是被阅读和引用的作家，不是游戏中虚构街头事件的见证人。", "sources": []}, "person-mallarme": {"intro": "法国诗人，关注语言、诗歌与表达形式。他的名字提示读者留意文学如何组织经验，而非仅记录事件。", "sources": []}, "person-gautier": {"intro": "法国诗人、小说家与艺术批评家。他活跃于文学和艺术世界，其见闻与评论构成十九世纪文化生活的材料。", "sources": []}, "person-du-camp": {"intro": "法国作家和摄影者，写过巴黎的城市生活与机构。他提供的是带有作者立场的观察，不能把全部叙述都当成中立统计。", "sources": []}, "person-fournel": {"intro": "法国作家、记者与巴黎生活的观察者。他笔下的街道、娱乐和行人，为本雅明提供了都市日常的文字材料。", "sources": []}, "person-lefeuve": {"intro": "法国作家、巴黎地方史书写者。其街道沿革记录帮助读者把抽象的城市变化落实到具体地名。", "sources": []}, "person-rachel": {"intro": "法国舞台演员拉歇尔，以古典悲剧表演著称。她属于剧院、名声与城市公众文化的历史，而不是同名的虚构人物。", "sources": []}, "person-mires": {"intro": "法国金融家和报业经营者。他的名字与信用、投机及第二帝国时期的商业世界相关。", "sources": []}, "person-boucicaut": {"intro": "法国商人，与乐蓬马歇百货的发展密切相关。他的经营实践使百货店成为研究商品陈列和现代消费的重要对象。", "sources": []}, "person-louis-philippe": {"intro": "法国七月王朝时期的国王。他的统治构成书中一部分商业、政治和城市生活材料的时代背景。", "sources": []}, "person-napoleon3": {"intro": "法国第二帝国皇帝，巴黎的大规模改造发生在其统治时期。他与奥斯曼是不同的人物，前者提供政治统治背景，后者主持具体改造。", "sources": []}, "person-kafka": {"intro": "德语作家，《审判》《城堡》等作品的作者。他属于本雅明的文学研究视野，并不是十九世纪巴黎街头生活的记录者。", "sources": []}, "group-flaneur": {"intro": "在城市中漫步并观察街景、人群和橱窗的人；它是一种观看和生活姿态，不是一份正式职业。", "sources": []}, "group-ragpicker": {"intro": "靠收集、分类和出售废纸、旧布等可再利用物品谋生的人。这里先是一种劳动者身份，随后才成为文学中的城市形象。", "sources": []}, "group-collector": {"intro": "有意识地寻找、保存和整理物品的人。藏品可以离开原来的交易用途，被放进个人的收藏秩序之中。", "sources": []}, "group-clerk": {"intro": "在商店中负责销售、接待、理货等工作的雇员。顾客看到的陈列与服务，背后都有具体的工时和劳动。", "sources": []}, "group-gambler": {"intro": "把金钱或财物押在不确定结果上的参与者。书中的赌徒涉及下注、等待和重复，并非所有娱乐场所的观众。", "sources": []}, "group-sexworker": {"intro": "以提供性服务获取报酬的人。书中使用过带有时代色彩的称谓；阅读这些材料时，仍应把她们理解为具有生活、劳动与不同处境的人。", "sources": []}, "group-dandy": {"intro": "把衣着、举止和自我风格看得极重的都市人物。丹蒂并不简单等于富人，也不是一种固定职业。", "sources": []}, "group-badaud": {"intro": "因街头事件、表演或人群而驻足围观的人。与持续观察的游荡者相比，这个称呼更强调被眼前热闹吸引的状态。", "sources": []}, "group-worker": {"intro": "依靠受雇劳动获取收入的人，包括工场工人、建筑工、搬运工等。不同工种的生活条件并不相同。", "sources": []}, "group-conspirator": {"intro": "通过秘密组织、联络和策划从事政治活动的人。书中语境主要联系革命社团，不是泛指一切心怀阴谋的坏人。", "sources": []}, "group-stockbroker": {"intro": "为证券交易提供中介服务的人；经纪人与自己承担风险下注的投机者并非完全相同，阅读时应结合具体段落区分。", "sources": []}, "group-detective": {"intro": "根据线索调查事件或辨认人物的人，也是一种文学角色。大都市的陌生人和人群，为侦探故事提供了环境。", "sources": []}, "group-sandwich": {"intro": "在身体前后悬挂广告牌、沿街替商家宣传的劳动者。名称来自人被两块牌子夹在中间的样子，与售卖三明治无关。", "sources": []}, "group-rentier": {"intro": "主要依靠财产收益、租金或利息生活的人。“食利者”强调收入来源，不等于所有房东或所有有钱人。", "sources": []}, "group-poet": {"intro": "从事诗歌写作的人。书中诗人既创造城市形象，也可能面对报刊、市场、声名和生计的压力。", "sources": []}};
for(const e of atlasEntries){const a=atlasIntroductions[e.id];e.intro=a.intro;e.bookDescription=e.description;e.description=a.intro+' 在本书的阅读线索中，'+e.bookDescription;e.onlineSources=a.sources}
const introArchiveOriginal=archiveCard;
archiveCard=function(e){return introArchiveOriginal(e).replace('<p>'+esc(e.en)+'</p>','<p>'+esc(e.en)+'</p><p class="identity-preview">'+esc(e.intro)+'</p>')};
const introDossierOriginal=dossierPage;
dossierPage=function(id){const e=atlasById.get(id),html=introDossierOriginal(id);if(!e)return html;return html.replace('<small>'+e.sourceNote+'</small>','<small>身份简介与原书主题分列理解。'+e.sourceNote+'</small><div class="identity-sources">'+e.onlineSources.map(s=>'<a href="'+s.url+'" target="_blank" rel="noopener noreferrer">'+esc(s.label)+' ↗</a>').join('')+'</div>')};

const identityExtraSources={"place-lauzun": ["巴黎市政厅 · 宅邸历史", "https://www.paris.fr/pages/l-hotel-de-lauzun-tresor-cache-de-l-ile-saint-louis-15679"], "place-catacombs": ["巴黎市政厅 · 地下墓穴", "https://www.paris.fr/pages/1-lieu-3-histoires-les-catacombes-34819"], "place-bonmarche": ["法国国家图书馆 · 百货商业史", "https://www.bnf.fr/fr/mediatheque/les-grands-magasins-aux-sources-du-commerce-moderne"], "person-boucicaut": ["法国国家图书馆 · 百货商业史", "https://www.bnf.fr/fr/mediatheque/les-grands-magasins-aux-sources-du-commerce-moderne"], "person-balzac": ["巴尔扎克故居 · 作品导读", "https://www.maisondebalzac.paris.fr/loeuvre-de-balzac/les-cles-de-lecture"], "group-rentier": ["Larousse · 词义", "https://www.larousse.fr/dictionnaires/francais/rentier/68257"], "group-badaud": ["CNRTL · 词义", "https://www.cnrtl.fr/definition/badaud"], "group-sandwich": ["百科 · 身份说明", "https://fr.wikipedia.org/wiki/Homme-sandwich"], "group-flaneur": ["百科 · 都市漫步者", "https://en.wikipedia.org/wiki/Fl%C3%A2neur"], "group-ragpicker": ["法兰西学院词典 · 身份说明", "https://www.dictionnaire-academie.fr/article/A9C2005"]};for(const [id,[label,url]] of Object.entries(identityExtraSources))atlasById.get(id).onlineSources.push({label,url});
render();

const personIdentitySources={"person-baudelaire": {"label": "百科身份资料 · Charles Baudelaire", "url": "https://en.wikipedia.org/wiki/Charles_Baudelaire"}, "person-fourier": {"label": "百科身份资料 · Charles Fourier", "url": "https://en.wikipedia.org/wiki/Charles_Fourier"}, "person-haussmann": {"label": "百科身份资料 · Georges-Eugène Haussmann", "url": "https://en.wikipedia.org/wiki/Georges-Eug%C3%A8ne_Haussmann"}, "person-balzac": {"label": "百科身份资料 · Honoré de Balzac", "url": "https://en.wikipedia.org/wiki/Honor%C3%A9_de_Balzac"}, "person-breton": {"label": "百科身份资料 · André Breton", "url": "https://en.wikipedia.org/wiki/Andr%C3%A9_Breton"}, "person-poe": {"label": "百科身份资料 · Edgar Allan Poe", "url": "https://en.wikipedia.org/wiki/Edgar_Allan_Poe"}, "person-marx": {"label": "百科身份资料 · Karl Marx", "url": "https://en.wikipedia.org/wiki/Karl_Marx"}, "person-engels": {"label": "百科身份资料 · Friedrich Engels", "url": "https://en.wikipedia.org/wiki/Friedrich_Engels"}, "person-saintsimon": {"label": "百科身份资料 · Henri de Saint-Simon", "url": "https://en.wikipedia.org/wiki/Henri_de_Saint-Simon"}, "person-simmel": {"label": "百科身份资料 · Georg Simmel", "url": "https://en.wikipedia.org/wiki/Georg_Simmel"}, "person-jung": {"label": "百科身份资料 · Carl Jung", "url": "https://en.wikipedia.org/wiki/Carl_Jung"}, "person-bloch": {"label": "百科身份资料 · Ernst Bloch", "url": "https://en.wikipedia.org/wiki/Ernst_Bloch"}, "person-hessel": {"label": "百科身份资料 · Franz Hessel", "url": "https://en.wikipedia.org/wiki/Franz_Hessel"}, "person-meryon": {"label": "百科身份资料 · Charles Meryon", "url": "https://en.wikipedia.org/wiki/Charles_Meryon"}, "person-daumier": {"label": "百科身份资料 · Honoré Daumier", "url": "https://en.wikipedia.org/wiki/Honor%C3%A9_Daumier"}, "person-wiertz": {"label": "百科身份资料 · Antoine Wiertz", "url": "https://en.wikipedia.org/wiki/Antoine_Wiertz"}, "person-michelet": {"label": "百科身份资料 · Jules Michelet", "url": "https://en.wikipedia.org/wiki/Jules_Michelet"}, "person-rimbaud": {"label": "百科身份资料 · Arthur Rimbaud", "url": "https://en.wikipedia.org/wiki/Arthur_Rimbaud"}, "person-boucicaut": {"label": "百科身份资料 · Aristide Boucicaut", "url": "https://en.wikipedia.org/wiki/Aristide_Boucicaut"}, "person-kafka": {"label": "百科身份资料 · Franz Kafka", "url": "https://en.wikipedia.org/wiki/Franz_Kafka"}};for(const [id,source] of Object.entries(personIdentitySources)){const e=atlasById.get(id);if(!e.onlineSources.some(s=>s.url===source.url))e.onlineSources.push(source)}
render();
